CONTINENTS.forEach(c=>c.rings=CONTOUR[c.k]||[]);
const mapC=document.getElementById('map'),mx=mapC.getContext('2d');
let MW=400,MH=230,selectedGeo=0,geoQuizOn=false,geoTarget=-1;
const lon2x=l=>(l+180)/360*MW;
/* Equal-area (Lambert cylindrical) rather than the usual equirectangular.
   On a plain lat/lon grid Antarctica draws at 34% of the world's land and
   Africa at 11%; the truth is 9% and 20%. With y=sin(lat) every continent
   lands within ~2% of its real share, so the first world map he ever sees
   is not the one that makes Africa look small. */
/* The stretch wasn't only the projection — it was the canvas shape. A
   cylindrical map has a natural width:height, and forcing it into a
   differently-proportioned box squashes every continent. Equal-area in a
   1.35 box stretched Africa to h/w 2.28 when the truth is 1.45.
   Now: plain lat/lon, cropped to 80S-84N (the polar caps are empty and
   they are where this projection distorts worst), drawn at 1.6:1 — which
   reproduces Africa at h/w 1.44. Shapes he can recognise come first. */
const LAT_HI=84, LAT_LO=-80;
const lat2y=l=>{
  const c=Math.max(LAT_LO,Math.min(LAT_HI,l));
  return (LAT_HI-c)/(LAT_HI-LAT_LO)*MH;
};
function fitMap(){
  const r=mapC.getBoundingClientRect(); if(!r.width) return;
  const dpr=Math.min(window.devicePixelRatio||1,3);
  MW=r.width; MH=r.width/1.6;
  mapC.width=MW*dpr; mapC.height=MH*dpr;
  mx.setTransform(dpr,0,0,dpr,0,0);
  drawMap();
}
new ResizeObserver(fitMap).observe(mapC);
function lighten(hex){
  const n=parseInt(hex.slice(1),16);
  const r=Math.min(255,(n>>16)+55),g=Math.min(255,((n>>8)&255)+55),b=Math.min(255,(n&255)+55);
  return `rgb(${r},${g},${b})`;
}
function contPath(c){
  mx.beginPath();
  c.rings.forEach(ring=>{
    ring.forEach((p,i)=>{const x=lon2x(p[0]),y=lat2y(p[1]);i?mx.lineTo(x,y):mx.moveTo(x,y);});
    mx.closePath();
  });
}
function drawMap(){
  if(!MW) return;
  mx.clearRect(0,0,MW,MH);
  mx.fillStyle='#123A63';mx.fillRect(0,0,MW,MH);
  mx.strokeStyle='rgba(255,255,255,.10)';mx.lineWidth=1;      // equator + grid
  [-60,-30,0,30,60].forEach(l=>{mx.beginPath();mx.moveTo(0,lat2y(l));mx.lineTo(MW,lat2y(l));mx.stroke();});
  [-120,-60,0,60,120].forEach(l=>{mx.beginPath();mx.moveTo(lon2x(l),0);mx.lineTo(lon2x(l),MH);mx.stroke();});
  CONTINENTS.forEach((c,i)=>{
    const sel=(i===selectedGeo&&!geoQuizOn);
    contPath(c);
    mx.fillStyle=sel?lighten(c.col):c.col; mx.fill();
    // a thick highlight stroke on a 4000-point coastline drowns the fill,
    // so selection is shown by brightening + a thin ring, not a fat outline
    mx.lineWidth=sel?2.2:1.4;
    mx.strokeStyle=sel?'#FFD400':'rgba(5,6,15,.85)';
    mx.stroke();
  });
  CONTINENTS.forEach((c,i)=>{                                  // labels
    const cx=lon2x(c.at[0]), cy=lat2y(c.at[1]);
    const name=c[lang][0].replace(/^(la|the|die)\s+/i,'');
    mx.font='700 '+Math.max(8,Math.min(13,MW*0.026))+'px Trebuchet MS, sans-serif';
    mx.textAlign='center';mx.textBaseline='middle';
    mx.lineWidth=3;mx.strokeStyle='rgba(5,6,15,.55)';
    mx.strokeText(name,cx,cy);
    mx.fillStyle=i===selectedGeo&&!geoQuizOn?'#FFD400':'#fff';
    mx.fillText(name,cx,cy);
  });
}
/* Point-in-polygon done here rather than with ctx.isPointInPath: that API
   requires the browser to transform the tap point by the canvas matrix, and
   some Android WebViews don't, which made every inland tap miss. */
function pointInRings(px,py,rings){
  let inside=false;
  for(const ring of rings){
    for(let i=0,j=ring.length-1;i<ring.length;j=i++){
      const xi=lon2x(ring[i][0]),yi=lat2y(ring[i][1]);
      const xj=lon2x(ring[j][0]),yj=lat2y(ring[j][1]);
      if(((yi>py)!==(yj>py)) && (px<(xj-xi)*(py-yi)/(yj-yi)+xi)) inside=!inside;
    }
  }
  return inside;
}
function segDist(px,py,ax,ay,bx,by){
  const dx=bx-ax,dy=by-ay,L=dx*dx+dy*dy;
  let t=L?((px-ax)*dx+(py-ay)*dy)/L:0;
  t=Math.max(0,Math.min(1,t));
  return Math.hypot(px-(ax+dx*t),py-(ay+dy*t));
}
function hitContinent(px,py){
  // Europe is tested before Asia, so the genuinely shared ground
  // (Turkey, western Russia) resolves to Europe rather than at random
  const order=[1,0,2,3,4,5,6];
  for(const i of order){
    if(pointInRings(px,py,CONTINENTS[i].rings)) return i;
  }
  // nothing hit exactly — fall back to the nearest outline, so small
  // fingers on Europe or Oceania still land somewhere sensible
  // Simplified coastlines put some coastal points a pixel or two offshore,
  // and small fingers miss small shapes — so fall back to the nearest outline
  // within a generous radius rather than ignoring the tap.
  let best=-1,bd=1e9;
  CONTINENTS.forEach((c,i)=>{
    c.rings.forEach(r=>{
      for(let k=0,m=r.length-1;k<r.length;m=k++){
        const d=segDist(px,py,lon2x(r[m][0]),lat2y(r[m][1]),lon2x(r[k][0]),lat2y(r[k][1]));
        if(d<bd){bd=d;best=i;}
      }
    });
  });
  return bd<MW*0.09?best:-1;
}
mapC.addEventListener('pointerdown',e=>{
  e.preventDefault();ac();
  const r=mapC.getBoundingClientRect();
  const i=hitContinent(e.clientX-r.left,e.clientY-r.top);
  if(i<0) return;
  if(geoQuizOn) geoAnswer(i); else geoSelect(i,true);
});
function geoSelect(i,speak){
  selectedGeo=i;const c=CONTINENTS[i];
  document.getElementById('geoName').textContent=c[lang][0];
  document.getElementById('geoText').textContent=c[lang][1];
  drawMap();
  if(speak!==false){say(c[lang][0]+'. '+c[lang][1]);beep(660,0,0.12,'square',0.14);}
}
