let geoQText='',geoMiss=0;
function geoAsk(){
  geoQuizOn=true;geoMiss=0;
  const L=level('geo',2);
  if(L>=2&&Math.random()<0.7){const q=pick(GEO_Q);geoTarget=CONTINENTS.findIndex(c=>c.k===q.a);geoQText=q[lang];}
  else{geoTarget=Math.floor(Math.random()*CONTINENTS.length);const n=CONTINENTS[geoTarget][lang][0];
    geoQText=lang==='es'?`¿Dónde está ${n}?`:lang==='de'?`Wo ist ${n}?`:`Where is ${n}?`;}
  document.getElementById('geoName').textContent='🎯 '+L;
  document.getElementById('geoText').textContent=geoQText;
  drawMap();say(geoQText);
}
function geoAnswer(i){
  if(i===geoTarget){
    geoQuizOn=false;bigWin();award(geoMiss);adapt('geo',2,geoMiss===0);
    geoSelect(i,true);
  }else{nope();geoMiss++;if(geoMiss===2)say(geoQText);}
}
document.getElementById('geoQuiz').onclick=()=>{ac();geoAsk();};
document.getElementById('geoSay').onclick=()=>{ac();
  if(geoQuizOn)say(geoQText);
  else geoSelect(selectedGeo,true);};
